import uPlot, { Axis as UAxis, Hooks, Series, Options, Plugin } from 'uplot';
import Yagr, { YagrMeta, YagrState } from './index';
import { TooltipOptions } from './plugins/tooltip/types';
import { LegendOptions } from './plugins/legend/legend';
import { CursorOptions } from './plugins/cursor/cursor';
declare type AllSeriesOptions = ExtendedSeriesOptions & CommonSeriesOptions & Omit<DotsSeriesOptions, 'type'> & Omit<LineSeriesOptions, 'type'> & Omit<AreaSeriesOptions, 'type'> & Omit<ColumnSeriesOptions, 'type'>;
declare module 'uplot' {
    interface Series extends Omit<AllSeriesOptions, 'data'> {
        id: string;
        color: string;
        name: string;
        /** Will appear after processing series */
        $c: DataSeriesExtended;
        /** Will appear after processing series if serie values normalized */
        normalizedData?: DataSeries;
        /** Does line have only null values */
        empty?: boolean;
        /** Real values count */
        count: number;
        /** Values sum */
        sum: number;
        /** Average value */
        avg: number;
        /** Get focus color */
        getFocusedColor: (y: Yagr, idx: number) => string;
        /** Current focus state */
        _focus?: boolean | null;
        /** Is series data transformd */
        _transformed?: boolean;
    }
}
/**
 * Main Yagr chart config
 */
export interface YagrConfig {
    /** Main chart visualization config */
    chart: YagrChartOptions;
    /** Graph title style. To customize other properties use CSS */
    title: {
        text: string;
        fontSize?: number;
    };
    /** Chart inline legend configuration */
    legend: LegendOptions;
    /** Config for axes. Determines style and labeling */
    axes: Record<string, AxisOptions>;
    /** Options for cursor plugin. Determines style, visibility and points render */
    cursor: CursorOptions;
    /** Timestamps */
    timeline: number[];
    /** Tooltip config. Detemines tooltip's behavior */
    tooltip: Partial<TooltipOptions>;
    /** Grid options (applies to all axes, can be overrided by axis.grid). */
    grid: UAxis.Grid;
    /** Marker visualisation options */
    markers: MarkersOptions;
    /** Scales options */
    scales: Record<string, Scale>;
    /** Raw series data and options */
    series: RawSerieData[];
    /** uPlot hooks + Yagr hooks */
    hooks: YagrHooks;
    /** Yagr data processing options */
    processing?: ProcessingSettings;
    /** uPlot options transform method */
    editUplotOptions?: (opts: Options) => Options;
    /** Additional Yagr plugins */
    plugins: Record<string, YagrPlugin>;
}
export declare type MinimalValidConfig = Partial<YagrConfig> & {
    timeline: Number[];
    series: RawSerieData[];
};
declare type ArrayElement<ArrayType extends readonly unknown[] | undefined> = ArrayType extends undefined ? never : ArrayType extends readonly (infer ElementType)[] ? ElementType : never;
declare type AsNonUndefined<T> = T extends undefined ? never : T;
declare type CommonHookHandlerArg<T> = T & {
    chart: Yagr;
};
export declare type HookParams<T extends YagrHooks[keyof YagrHooks]> = T extends undefined ? never : Parameters<AsNonUndefined<ArrayElement<T>>>;
export declare type HookHandler<Data> = ((a: CommonHookHandlerArg<Data>) => void)[];
export declare type LoadHandlerArg = CommonHookHandlerArg<{
    meta: YagrMeta;
}>;
export declare type OnSelectHandlerArg = CommonHookHandlerArg<{
    from: number;
    to: number;
}>;
export declare type ErrorHandlerArg = CommonHookHandlerArg<{
    type: YagrState['stage'];
    error: Error;
}>;
export declare type ProcessedHandlerArg = CommonHookHandlerArg<{
    meta: Pick<YagrMeta, 'processTime'>;
}>;
export declare type InitedHandlerArg = CommonHookHandlerArg<{
    meta: Pick<YagrMeta, 'initTime'>;
}>;
export declare type DisposeHandlerArg = CommonHookHandlerArg<{}>;
export declare type ResizeHandlerArg = CommonHookHandlerArg<{
    entries: ResizeObserverEntry[];
}>;
export interface YagrHooks extends Hooks.Arrays {
    load?: HookHandler<{
        meta: YagrMeta;
    }>;
    onSelect?: HookHandler<{
        from: number;
        to: number;
    }>;
    error?: HookHandler<{
        error: Error;
        stage: YagrState['stage'];
    }>;
    processed?: HookHandler<{
        meta: Pick<YagrMeta, 'processTime'>;
    }>;
    inited?: HookHandler<{
        meta: Pick<YagrMeta, 'initTime'>;
    }>;
    dispose?: HookHandler<{}>;
    resize?: HookHandler<{
        entries: ResizeObserverEntry[];
    }>;
    stage?: HookHandler<{
        stage: YagrState['stage'];
    }>;
}
export interface ProcessingInterpolation {
    /** Interpolation type */
    /**
     * - previous: takes previous existing value
     * - left: takes previous existing value except for last point
     * - next: takes next existing value
     * - right: takes next existing value except for first point
     * - linear: calcs value by linear interpolation
     * - closes: takes closes existing value
     */
    type: 'previous' | 'left' | 'next' | 'right' | 'linear' | 'closest';
    /** Cursor and tooltip snapToValue option */
    snapToValues?: SnapToValue | false;
    /** Values to interpolate */
    value?: unknown;
}
export interface ProcessingSettings {
    /** Should interpolate missing data (default: undefined) */
